with metrics as (select *, avg(amount) over w_running as amount_avg_3, lead(amount, 1, 0) over (partition by method order by paid_at, id) as next_amount, avg(amount) over w_part as amount_avg_3_2, row_number() over w_hist as seq_no from payments window w_running as (partition by order_id order by amount, id rows between 3 preceding and current row), w_part as (order by paid_at, id rows between 3 preceding and current row), w_hist as (partition by method, status order by paid_at desc, id)) select date_trunc('year', paid_at) as year_start, date_trunc('quarter', paid_at) as quarter_start, method, count(*) as row_count, round(sum(next_amount) / nullif(count(case when status = 'SUCCESS' then 1 end), 0), 2) as next_amount_per_success, avg(amount_avg_3_2) as avg_amount_avg_3_2 from metrics group by date_trunc('year', paid_at), date_trunc('quarter', paid_at), method having next_amount_per_success >= 0
